sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    if (api.state.newRiskEventId != -1) {
        helpers
            .translate('Risk event is successfully created for ' + api.data.look_up_new_risk_event_record.result.primary_profile.displayValue + '.')
            .then((val) => {
                api.setState('successMessage', val);
            });
    }
}
